INSERT INTO `master_soals` VALUES (3731,NULL,'Berikut ini uraian yang benar tentang pajak, adalah ?',1,147,'4','Iuran wajib kepada negara sesuai UU dan tidak mendapatkan balas jasa secara langsung','Iuran yang harus dibayar wajib pajak dan akan memperoleh balas jasa secara langsung','Iuran wajib pajak yang dibayar dengan sukarela','Iuran yang diatur dengan UU dan bersifat wajib','Iuran yang dipungut negara berdasarkan UU yang bersifat sukarela','A',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3732,NULL,'Pajak digunakan untuk menekan inflasi dengan cara mengatur peredaran uang di masyarakat lewat pemungutan dan penggunaan pajak yang lebih efisien dan efektif merupakan fungsi ?',1,147,'4','Finansial','Mengatur ','Stabilitas','Retribusi Pendapatan ','Pemerataan ','B',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3733,NULL,'Fungsi pajak budgetair yaitu ?',1,147,'4','Pajak merupakan sumber bagi negara untuk memperoleh pendapatan','Pajak sebagai alat untuk mengatur atau melaksanakan kebijakan pemerintah dalam bidang sosial dan ekonomi serta mencapai tujuan- tujuan tertentu di luar bidang keuangan','Pajak sebagai sumber bagi negara untuk memperoleh pendapatan','Pajak dapat digunakan untuk menyesuaikan dan menyeimbangkan antara pembagian pendapatan dengan kebahagiaan dan kesejahteraan masyarakat','Pajak yang sudah dipungut oleh negara akan digunakan untuk membiayai semua kepentingan umum','A',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3734,NULL,'Di bawah ini yang termasuk hukum pajak formal adalah ?',1,147,'4','Tata Cara Pendaftaran PKP','Siapa yang dikenai (subjek pajak)','Segala sesuatu tentang timbul dan hapusnya utang pajak','Tarif Pajak','Peristiwa hukum yang dikenai pajak (objek pajak)','A',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3735,NULL,'PPN dan PPh secara berturut turut, berdasarkan sifatnya merupakan pajak jenis ?.',1,147,'4','A. Pajak langsung dan tidak langsung','B. Pajak tidak langsung dan langsung','C. Pajak subjektif dan objektif','D.?Pajak objektif dan subjektif','E. Pajak tidak langsung dan objektif','',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3736,NULL,'Nomor yang diberikan kepada Wajib Pajak sebagai sarana dalam adminsitrasi perpajakan yang dipergunakan sebagai tanda pengenal diri atau identitas Wajib Pajak dalam melaksanakan hak dan kewajiban perpajakan merupakan pengertian dari?.',1,147,'4','Nomor Wajib Pajak','nomor identitas wajib pajak','nomor administrasi','nomor urut wajib pajak','Nomor Pokok Wajib Pajak','E',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3737,NULL,'Berikut ini fungsi dari NPWP, kecuali...',1,147,'4','pengusaha yang telah dikukuhkan sebagai pengusaha kena pajak yang telah tercatat dalam kantor pelayanan Pajak (KPP)','untuk menjaga ketertiban dalam melaksanakan pajak dan dalam pengawasan administrasi perpajakan','untuk memenuhi kewajiban-kewajiban perpajakan',' sebagai sarana dalam administrasi perpajakan yang digunakan sebagai tanda pengenal atau identitas wajib pajak','untuk keperluan pelaporan SPT masa dan tahunan','C',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3738,NULL,'Setiap warga Negara yang telah memenuhi persyaratan subjektif dan/atau objektif dalam bidang perpajakan berhak untuk memperoleh NPWP dijelaskan dalam pasal?.',1,147,'4','A. Pasal 1 ayat 1 UU KUP','B.?Pasal 2 ayat 1 UU KUP','C. Pasal 3 ayat 1 UU KUP','D. Pasal 4 ayat 1 UU KUP','E. Pasal 5 ayat 1 UU KUP','B',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3739,NULL,'Setiap warga Negara yang telah memenuhi persyaratan di bidang perpajakan diwajibkan memperoleh NPWP. Persyaratan bagi subjek pajak yang menerima atau memperoleh penghasilan diwajibkan untuk melakukan pemungutan pajak sesuai dengan Undang-Undang merupakan persyaratan?',1,147,'4','objektif','subjektif','administative','wajib pajak','registrasi','A',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3740,NULL,'Bentuk usaha yang digunakan untuk menjalankan kegiatan usaha secara teratur di Indonesia oleh badan atau perusahaan yang tidak didirikan atau tidak berkedudukan di Indonesia merupakan pengertian dari?.',1,147,'4','Badan Usaha Tetap','Badan Kena Pajak','Bentuk Usaha Tetap','Usaha Pribadi','Bentuk Usaha Mandiri','C',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3741,NULL,'Perhatikan dokumen berikut ini!\na) fotokopi pendirian dan perubahan terakhir atau surat keterangan penujukkan dari kantor pusat bagi bentuk usaha tetap\nb) fotokopI KTP bagi penduduk Indonesia atau fotokopi paspor dan surat keterangan tempat tinggal dari instansi yang berwenang minimal lurah atau kepala desa bagi orang asingmdari salah seorang pengurus aktif\nc) surat keterangan tempat kegiatan usaha atau pekerjaan bebas dari instansi yang berwenang, minimal lurah atau kepala desa\nKelengkapan dokumen diatas merupakan syarat untuk memperoleh Nomor Pokok Wajib Pajak (NPWP) untuk wajib pajak?.',1,147,'4','orang pribadi tidak menjalankan usaha','orang pribadi menjalankan usaha','bendaharawan ','badan ','joint operation','D',NULL,24,NULL,'2022-05-22 16:01:31',NULL),(3742,NULL,'Perhatikan pernyataan berikut ini!\na) Wajib Pajak dan/atau ahli warisnya karena Wajib Pajak sudah tidak memenuhi persyaratan subjektif dan/atau objektif sesuai dengan ketentuan peraturan perundang-undangan perpajakan\nb) Wanita kawin yang sebelumnya telah memiliki NPWP dan menikah tanpa membuat perjanjian pemisahan harta serta suaminya telah terdaftar sebagai Wajib Pajak, disyaratkan adanya surat nikah/akta perkawinan dari catatan sipil;\nc) Wajib Pajak Badan dalam rangka likuidasi atau telah dibubarkan secara resmi, disyaratkan adanya akta pembubaran;\nd) Bentuk Usaha Tetap (BUT) yang karena sesuatu hal kehilangan statusnya sebagai BUT, disyaratkan adanya permohonan Wajib Pajak yang dilampiri dokumen yang mendukung bahwa BUT tersebut tidak memenuhi syarat lagi untuk dapat digolongkan sebagai Wajib Pajak\nPernyataan diatas merupakan penyebab terjadinya?.',1,147,'4','Pengusaha Kena Pajak pindah','Penghapusan NPWP','Pencabutan NPWP','pendaftaran NPWP ','Perubahan Data WP','B',NULL,24,NULL,'2022-05-22 16:01:31',NULL