 02:49:17',NULL),(5494,'','<p><img alt=\"\" src=\"https://gtk.smkpandawabaliglobal.sch.id/./asset/soals/7_202209150250.jpg\" style=\"height:183px; width:276px\" /></p>\r\n\r\n<p>Alat di atas ini merupakan alat pengolahan pembuatan bumbu dasar, apa nama alat tersebut ...</p>\r\n',1,72,'1','<p>Cobek</p>\r\n','<p>Alu</p>\r\n','<p>Blender</p>\r\n','<p>Ulek</p>\r\n','','A',NULL,7,NULL,'2022-09-14 18:50:39',NULL),(5495,NULL,'Rendang merupakan hidangan yang menggunakan bumbu dasar ?.',1,72,'1','Bumbu Dasar Merah','\n\nBumbu Dasar Kuning\n','Bumbu Dasar Putih','\n\nBumbu Dasar Hitam\n','','A',NULL,7,NULL,'2022-09-15 02:49:17',NULL),(5496,NULL,'Dalam pembuatan bumbu dasar dipergunakan teknik memasak, agar menghasilkan rasa yang khas, tehnik pembuatan bumbu dasar, Antara lain ...\n',1,72,'1','\n\nDiaduk\n','\n\nDicampur\n\n\n','Ditumis','\n\nDiiris\n','','C',NULL,7,NULL,'2022-09-15 02:49:17',NULL),(5497,NULL,'Bumbu dasar kuning mempunyai ciri khas berwarna kuning, warna kuning pada bumbu dasar tersebut diperoleh dari : ?\n',1,72,'1','Chilli','Ginger','Turmeric','Nutmeg','','C',NULL,7,NULL,'2022-09-15 02:49:17',NULL),(5498,NULL,'Pengertian wadah hidang adalah ?\n',1,72,'1','\nWadah atau tempat untuk menyajikan hidangan','Wadah atau tempat untuk makan','Wadah atau tempat untuk masak','Wadah atau tempat yang indah','','A',NULL,7,NULL,'2022-09-15 02:49:17',NULL),(5499,NULL,' \n\nKapan Wadah Hidang Dari Sayur dan Buah digunakan ?\n',1,72,'1','Pada setiap saat','Pada setiap makan siang','Pada setiap makan malam','Pada saat acara jamuan makan','','D',NULL,7,NULL,'2022-09-15 02:49:17',NULL),(5500,NULL,'Wadah Hidang Dari Sayur Dan Buah biasa di gunakan sebagai ?\n',1,72,'1','Sebagai pelengkap hidangan','\nSebagai pusat perhatian','Sebagai wadah hidangan','\nSebagai hiasan','','C',NULL,7,NULL,'2022-09-15 02:49:17',NULL),(5501,NULL,'Di bawah ini yang bukan merupakan kriteria sayur untuk membuat wadah hidang adalah ?\n',1,72,'1','Bentuk sayur berupa buah atau batang','Bisa dimakan','warn