INSERT INTO `master_soals` VALUES (21783,NULL,'Berikut ini yang bukan termasuk karakteristik pajak adalah....',1,147,'1','Di Atur Dalam Undang-Undang','Tidak mendapat imbalan langsung atas pembayaran pajak','Bersifat memaksa untuk setiap warga negara','Kontribusi wajib warga negara','Dibayar Secara Sukarela','E',NULL,177,NULL,'2024-09-16 15:00:09',NULL),(21784,NULL,'Pajak dipungut oleh pemerintah daerah dan digunakan untuk pembiayaan rumah tangga daerah tingkat II adalah pajak...',1,147,'1','Pajak Penghasilan','Pajak Restoran','Bea Masuk','Bea Keluar','Kendaraan Bermotor','B',NULL,177,NULL,'2024-09-16 15:00:09',NULL),(21785,'Design Brief','<p>Apa yang dimaksud dengan <strong>design brief</strong> dalam proyek desain?</p>\r\n',1,269,'1','Konsep desain secara keseluruhan','Panduan tertulis untuk proyek desain','Hasil akhir dari proyek','Proses revisi desain','','B',NULL,137,'2024-09-16 15:17:48','2024-09-16 16:37:20',NULL),(21786,NULL,'Apa yang dimaksud dengan desain brief?',1,269,'3',' Dokumen untuk pengajuan proposal',' Dokumen berisi panduan klien mengenai proyek desain',' Dokumen teknis tentang spesifikasi produk',' Laporan keuangan perusahaan',' Rancangan anggaran biaya proyek desain','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21787,NULL,'Fungsi utama dari desain brief adalah...',1,269,'3',' Menentukan harga proyek',' Menyusun strategi pemasaran',' Menyediakan panduan bagi desainer dalam mengerjakan proyek',' Menyusun rencana keuangan',' Mengajukan desain ke klien','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21788,NULL,'Informasi berikut biasanya terdapat dalam desain brief, kecuali...',1,269,'3',' Tujuan proyek',' Target audiens',' Profil perusahaan',' Gaji desainer',' Hasil akhir yang diharapkan','D',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21789,NULL,'Mengapa target audiens penting dalam desain brief?',1,269,'3',' Agar desainer mengetahui profil klien',' Untuk menentukan budget proyek',' Agar desainer dapat menghasilkan desain yang sesuai dengan preferensi audiens',' Untuk mempermudah komunikasi dengan klien',' Untuk menentukan waktu pengerjaan','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21790,NULL,'Apa yang dimaksud dengan \"scope of work\" dalam desain brief?',1,269,'3',' Penjelasan tentang biaya proyek',' Deskripsi tentang ruang lingkup pekerjaan yang harus diselesaikan',' Waktu yang dibutuhkan untuk menyelesaikan proyek',' Daftar bahan yang dibutuhkan untuk proyek',' Syarat dan ketentuan kontrak','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21791,NULL,'Dalam desain brief, tujuan proyek biasanya berisi...',1,269,'3',' Detail teknis tentang software yang digunakan',' Deskripsi mengenai hasil akhir yang diinginkan',' Proses produksi desain',' Identifikasi gaya desain yang diinginkan',' Waktu pengerjaan proyek','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21792,NULL,'Berikut ini adalah komponen penting dari desain brief, kecuali...',1,269,'3',' Timeline proyek',' Biaya yang dianggarkan',' Target audiens',' Detail teknis perangkat keras',' Gaya desain yang diinginkan','D',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21793,NULL,'Apa yang biasanya dituliskan dalam bagian \"Timeline\" dari desain brief?',1,269,'3',' Waktu yang dihabiskan oleh setiap desainer',' Batas waktu penyelesaian proyek dan tenggat lainnya',' Detail tentang target audiens',' Biaya proyek per jam',' Rencana pemasaran','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21794,NULL,'Siapa yang bertanggung jawab membuat desain brief?',1,269,'3',' Desainer',' Klien',' Manajer proyek',' Copywriter',' Art Director','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21795,NULL,'Ketika desainer menemukan ketidaksesuaian antara desain brief dan permintaan klien, apa yang harus dilakukan desainer?',1,269,'3',' Mengikuti arahan yang diinginkan klien tanpa bertanya',' Melaporkan ketidaksesuaian kepada manajer proyek',' Berdiskusi kembali dengan klien untuk klarifikasi',' Membuat keputusan sendiri berdasarkan pengalaman',' Menyelesaikan proyek sesuai timeline','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21796,NULL,'Apakah penting bagi desainer untuk memahami visi jangka panjang klien dalam desain brief?',1,269,'3',' Tidak penting karena hanya berfokus pada proyek saat ini',' Penting untuk menyesuaikan desain dengan arah bisnis klien',' Tidak berpengaruh pada hasil desain',' Hanya penting untuk proyek besar',' Penting hanya jika ada permintaan khusus dari klien','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21797,NULL,'Bagian mana dari desain brief yang berisi deskripsi spesifik tentang bagaimana hasil akhir proyek harus terlihat?',1,269,'3',' Target audiens',' Budget',' Deliverables',' Timeline',' Scope of Work','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21798,NULL,'Klien meminta revisi yang tidak ada dalam desain brief. Apa langkah yang sebaiknya diambil desainer?',1,269,'3',' Menolak permintaan revisi',' Menambahkan revisi tanpa biaya tambahan',' Mengonfirmasi revisi sebagai tambahan pekerjaan dan mendiskusikan biaya tambahan',' Menyesuaikan jadwal tanpa memberi tahu klien',' Menyelesaikan revisi di akhir proyek','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21799,NULL,'Apa yang sebaiknya dilakukan jika klien tidak memberikan desain brief yang jelas?',1,269,'3',' Menerima proyek dan bekerja sesuai interpretasi pribadi',' Meminta informasi tambahan sebelum memulai pekerjaan',' Melakukan riset pasar tanpa arahan',' Meninggalkan proyek',' Membuat desain brief sendiri dan tidak melibatkan klien','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21800,NULL,'Dalam desain brief, revisi biasanya diatur dalam bagian mana?',1,269,'3',' Scope of Work',' Deliverables',' Budget',' Timeline',' Target Audiens','A',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21801,NULL,'Apa langkah pertama dalam proses produksi desain untuk konten media sosial?',1,269,'3',' Mengedit gambar',' Membuat sketsa desain',' Riset audiens dan tren',' Memilih platform sosial media',' Mengunggah konten','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21802,NULL,'Dalam membuat konten media sosial, apa yang perlu diperhatikan untuk menjaga identitas brand?',1,269,'3',' Warna, font, dan tone of voice',' Durasi video',' Jumlah pengikut',' Waktu posting',' Jumlah like yang didapat','A',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21803,NULL,'Mengapa penting untuk menentukan target audience sebelum memulai produksi konten?',1,269,'3',' Agar bisa membuat lebih banyak konten',' Untuk menyesuaikan konten dengan minat dan kebutuhan audiens',' Agar tidak memerlukan proses editing yang panjang',' Untuk mempercepat proses produksi',' Untuk menambah jumlah followers','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21804,NULL,'Apa yang dimaksud dengan call-to-action (CTA) dalam konten media sosial?',1,269,'3',' Tombol untuk membagikan konten',' Arah atau instruksi yang mendorong audiens untuk melakukan tindakan tertentu',' Jumlah pengikut yang harus dicapai',' Waktu unggahan konten',' Sketsa awal desain','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21805,NULL,'Platform media sosial mana yang lebih fokus pada konten berbasis gambar dan visual?',1,269,'3',' Twitter',' TikTok',' LinkedIn',' Instagram',' WhatsApp','D',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21806,NULL,'Apa yang harus diperhatikan dalam memilih format konten untuk media sosial?',1,269,'3',' Kualitas kamera yang digunakan',' Algoritma media sosial',' Karakteristik dan preferensi platform yang digunakan',' Jumlah pengikut yang dimiliki',' Budget untuk iklan','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21807,NULL,'Dalam proses produksi desain, aplikasi seperti Adobe Premiere biasa digunakan untuk...',1,269,'3',' Membuat ilustrasi',' Menyunting video',' Menulis caption',' Mendesain logo',' Membuat infografis','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21808,NULL,'Apa tujuan dari melakukan A/B testing dalam konten media sosial?',1,269,'3',' Menguji dua versi konten untuk melihat mana yang paling efektif',' Membuat dua akun media sosial yang berbeda',' Mengetes kualitas gambar dan video',' Menghitung jumlah interaksi dalam konten',' Memilih dua tema desain yang berbeda','A',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21809,NULL,'Apa yang dimaksud dengan engagement rate dalam konteks media sosial?',1,269,'3',' Jumlah total konten yang diunggah',' Persentase interaksi audiens terhadap konten yang diunggah',' Waktu yang dihabiskan audiens di akun media sosial',' Jumlah tayangan video',' Skor popularitas konten','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21810,NULL,'Dalam proses pembuatan konten, mengapa penggunaan visual hierarchy penting?',1,269,'3',' Agar konten terlihat lebih artistik',' Untuk menambah jumlah pengikut',' Membantu audiens fokus pada elemen yang paling penting dalam desain',' Agar konten bisa diunggah lebih cepat',' Untuk menambah durasi video','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21811,NULL,'Peran seorang content creator dalam tim pemasaran digital adalah...',1,269,'3',' Mengelola keuangan proyek',' Merancang strategi pemasaran',' Menghasilkan dan mengedit konten visual atau audio',' Menganalisis data penjualan',' Menghubungi influencer','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21812,NULL,'Apa yang harus dilakukan ketika konten yang diunggah tidak mendapatkan interaksi yang cukup?',1,269,'3',' Menghapus konten',' Mengubah seluruh strategi konten',' Menganalisis data dan melakukan perbaikan untuk konten berikutnya',' Mengunggah ulang konten yang sama',' Berhenti membuat konten sementara','C',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21813,NULL,'Konten berbasis video lebih efektif untuk...',1,269,'3',' Menyampaikan informasi secara mendalam dan menarik perhatian audiens',' Menampilkan grafik penjualan',' Menjaga feed media sosial tetap konsisten',' Meningkatkan pengikut dengan cepat',' Mengurangi biaya produksi','A',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21814,NULL,'Apakah yang dimaksud dengan content calendar?',1,269,'3',' Kalender yang menunjukkan hari libur nasional',' Alat untuk merencanakan dan menjadwalkan konten yang akan diunggah',' Waktu khusus untuk produksi konten',' Sistem otomatis untuk mengunggah konten',' Fitur pengingat untuk mengedit konten','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21815,NULL,'Dalam proses produksi konten, mengapa penting melakukan riset tentang kompetitor?',1,269,'3',' Untuk meniru konten mereka',' Untuk menghindari ide yang sudah dilakukan dan mengembangkan strategi unik',' Untuk mengurangi waktu produksi',' Agar konten lebih cepat selesai',' Untuk memilih format konten yang sesuai','B',NULL,137,NULL,'2024-09-16 15:17:52',NULL),(21816,'Design Brief','<p>Elemen berikut yang <strong>tidak</strong> termasuk dalam sebuah design brief adalah:<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Latar belakang proyek<br />\r\n&nbsp;</p>\r\n','<p>Tujuan proyek<br />\r\n&nbsp;</p>\r\n','<p>Media yang digunakan<br />\r\n&nbsp;</p>\r\n','<p>Pendanaan proyek</p>\r\n','','D',NULL,137,'2024-09-16 15:20:43','2024-09-16 15:20:43',NULL),(21817,'Design Brief','<p>Design brief biasanya diberikan oleh:<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>&nbsp;Desainer<br />\r\n&nbsp;</p>\r\n','<p>Pemberi tugas<br />\r\n&nbsp;</p>\r\n','<p>Produser<br />\r\n&nbsp;</p>\r\n','<p>Klien lain</p>\r\n','','B',NULL,137,'2024-09-16 15:27:26','2024-09-16 15:27:26',NULL),(21818,'Design Brief','<p>Apa peran dari <strong>target audience</strong> dalam design brief?<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Mengidentifikasi pihak yang mendanai proyek<br />\r\n&nbsp;</p>\r\n','<p>Menentukan siapa yang akan menikmati hasil desain<br />\r\n&nbsp;</p>\r\n','<p>Mengatur alur produksi<br />\r\n&nbsp;</p>\r\n','<p>Mengarahkan proses revisi</p>\r\n','','B',NULL,137,'2024-09-16 15:31:20','2024-09-16 15:31:20',NULL),(21819,'Design Brief','<p>Dalam proses produksi, tahapan pertama yang dilakukan adalah:<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Produksi<br />\r\n&nbsp;</p>\r\n','<p>Pasca-produksi<br />\r\n&nbsp;</p>\r\n','<p>Pra-produksi<br />\r\n&nbsp;</p>\r\n','<p>Penyusunan laporan</p>\r\n','','C',NULL,137,'2024-09-16 15:32:32','2024-09-16 15:32:32',NULL),(21820,'Proses Produksi','<p>Tahapan <strong>pra-produksi</strong> mencakup kegiatan berikut, kecuali:<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Riset<br />\r\n&nbsp;</p>\r\n','<p>Penyusunan sketsa<br />\r\n&nbsp;</p>\r\n','<p>Penyuntingan video<br />\r\n&nbsp;</p>\r\n','<p>Budgeting</p>\r\n','','C',NULL,137,'2024-09-16 15:33:47','2024-09-16 15:33:47',NULL),(21821,'Proses Produksi','<p>Proses <strong>produksi</strong> dalam sebuah proyek desain melibatkan:<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Riset<br />\r\n&nbsp;</p>\r\n','<p>Pengambilan gambar atau pembuatan desain<br />\r\n&nbsp;</p>\r\n','<p>Pengeditan hasil akhir<br />\r\n&nbsp;</p>\r\n','<p>Negosiasi dengan klien</p>\r\n','','B',NULL,137,'2024-09-16 15:35:03','2024-09-16 15:35:03',NULL),(21822,'Proses Produksi','<p><strong>Post-production</strong> adalah tahap yang biasanya melibatkan:<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Membuat storyboard<br />\r\n&nbsp;</p>\r\n','<p>Penyelesaian editing dan revisi<br />\r\n&nbsp;</p>\r\n','<p>Penulisan design brief<br />\r\n&nbsp;</p>\r\n','<p>Pembuatan anggaran</p>\r\n','','B',NULL,137,'2024-09-16 15:36:34','2024-09-16 15:36:34',NULL),(21823,'Design Brief','<p>Apa yang dimaksud dengan <strong>strategi kreatif</strong> dalam design brief?<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Rencana teknis untuk pelaksanaan proyek<br />\r\n&nbsp;</p>\r\n','<p>Cara mencapai tujuan desain secara kreatif<br />\r\n&nbsp;</p>\r\n','<p>Proses revisi desain<br />\r\n&nbsp;</p>\r\n','<p>Penentuan timeline proyek</p>\r\n','','B',NULL,137,'2024-09-16 15:38:03','2024-09-16 15:38:03',NULL),(21824,'Design Brief','<p>Ketika memilih media untuk suatu proyek desain, apa yang paling penting dipertimbangkan?<br />\r\n&nbsp;</p>\r\n',1,269,'1','<p>Jenis kamera yang digunakan<br />\r\n&nbsp;</p>\r\n','<p>Target audience dan tujuan proyek<br />\r\n&nbsp;</p>\r\n','<p>Waktu penyelesaian<br />\r\n&nbsp;</p>\r\n','<p>Keahlian desainer</p>